options(stringsAsFactors=FALSE)
suppressPackageStartupMessages({library(dplyr);library(tidyr)})
source('scripts/config.R');out<-temporal_dir
readpart<-function(prefix)bind_rows(lapply(1:2,function(p)read.csv(file.path(out,paste0(prefix,'_part',p,'.csv')))))
f<-readpart('A27_original_ARIMAX_forecasts');v<-readpart('A28_original_ARIMAX_validation')
write.csv(f,file.path(out,'A27_original_ARIMAX_forecasts.csv'),row.names=FALSE,na='')
write.csv(v,file.path(out,'A28_original_ARIMAX_validation.csv'),row.names=FALSE,na='')
stopifnot(length(unique(f$location_id))==204,nrow(f)==204*2*2*9,nrow(v)==204*2*27)
others<-read.csv(file.path(out,'A7_forecast_validation.csv'))%>%filter(model%in%c('Original_VARX_p2','Naive'))
v<-bind_rows(v,others)
sumcv<-function(z)z%>%group_by(model,disease)%>%summarise(n=n(),median_APE=median(APE),mean_APE=mean(APE),RMSE=sqrt(mean((median-actual)^2)),median_APE_clipped=median(APE_clipped),mean_APE_clipped=mean(APE_clipped),coverage95=if(all(is.na(covered)))NA_real_ else mean(covered),.groups='drop')
write.csv(sumcv(v%>%filter(origin%in%c(2012,2015,2018),h<=3)),file.path(out,'A30_original_model_short_validation.csv'),row.names=FALSE,na='')
write.csv(sumcv(v%>%filter(h==9)),file.path(out,'A31_original_model_nine_year_endpoint.csv'),row.names=FALSE,na='')
write.csv(v%>%filter(h==9)%>%group_by(model,disease,origin)%>%summarise(n=n(),median_APE=median(APE),mean_APE=mean(APE),RMSE=sqrt(mean((median-actual)^2)),coverage95=if(all(is.na(covered)))NA_real_ else mean(covered),.groups='drop'),file.path(out,'A32_original_model_nine_year_by_origin.csv'),row.names=FALSE,na='')
fw<-f%>%filter(h==9)%>%select(location_id,location_name,scenario,disease,median,lower,upper,clipped,order,serial_p)%>%pivot_wider(names_from=disease,values_from=c(median,lower,upper,clipped,order,serial_p))%>%arrange(location_id)%>%group_by(scenario)%>%mutate(qCKD=ntile(median_CKD,4),qDD=ntile(median_DD,4),qCKD_clip=ntile(clipped_CKD,4),qDD_clip=ntile(clipped_DD,4),HH=qCKD==4&qDD==4,HH_clip=qCKD_clip==4&qDD_clip==4,same=qCKD==qDD,same_clip=qCKD_clip==qDD_clip)%>%ungroup()
write.csv(fw,file.path(out,'A33_original_ARIMAX_2030_point_classification.csv'),row.names=FALSE,na='')
write.csv(fw%>%group_by(scenario)%>%summarise(n=n(),HH=sum(HH),HH_clip=sum(HH_clip),same=sum(same),same_clip=sum(same_clip),CKD_clipped=sum(abs(median_CKD-clipped_CKD)>1e-8),DD_clipped=sum(abs(median_DD-clipped_DD)>1e-8),.groups='drop'),file.path(out,'A34_original_ARIMAX_2030_summary.csv'),row.names=FALSE,na='')
write.csv(f%>%filter(h==1,scenario=='hold')%>%group_by(disease)%>%summarise(n=n(),residual_reject=sum(serial_p<.05,na.rm=TRUE),residual_NA=sum(is.na(serial_p)),invalid_point=sum(!is.finite(median)|median<0),.groups='drop'),file.path(out,'A36_original_ARIMAX_diagnostics.csv'),row.names=FALSE,na='')
